    @classmethod
    def _evaluate_checkpoint(
        cls,
        spec: Mapping[str, Any],
        rows: list[dict[str, Any]],
        *,
        window_start: datetime,
        window_end: datetime | None,
    ) -> tuple[dict[str, Any], datetime | None]:
        candidates: list[tuple[Message, str, datetime, dict[str, Any]]] = []
        for row in rows:
            raw = str(row.get("mimeMessage") or "").encode("utf-8")
            message = message_from_bytes(raw)
            subject = cls._decode_header(message.get("Subject") or row.get("subject") or "")
            if cls._normalize_subject(subject) != cls._normalize_subject(str(spec["subject"])):
                continue
            date = cls._message_date(message)
            if date is None or date < window_start or (window_end is not None and date > window_end):
                continue
            candidates.append((message, subject, date, row))

        reasons: list[str] = []
        observed: dict[str, Any] = {"candidate_count": len(candidates)}
        matched_date: datetime | None = None
        if len(candidates) != 1:
            reasons.append(f"expected exactly one in-window message, observed {len(candidates)}")
        if candidates:
            message, subject, matched_date, row = candidates[-1]
            plain_text = cls._plain_text(message)
            sender = parseaddr(message.get("From") or "")[1].casefold()
            recipients = {
                address.casefold()
                for _name, address in getaddresses(message.get_all("To", []) or [])
                if address
            }
            references = " ".join(
                filter(None, (message.get("In-Reply-To"), message.get("References")))
            )
            compact_references = re.sub(r"\s+", "", references).casefold()
            attachments = cls._attachment_summaries(message)
            observed.update(
                {
                    "uid": row.get("uid"),
                    "message_id": message.get("Message-ID") or row.get("Message-ID"),
                    "subject": subject,
                    "sender": sender,
                    "recipients": sorted(recipients),
                    "date": matched_date.isoformat(),
                    "body_prefix": plain_text[:160],
                    "references": references,
                    "attachments": attachments,
                }
            )
            if sender != SENDER_EMAIL:
                reasons.append(f"sender mismatch: {sender!r}")
            if str(spec["recipient"]).casefold() not in recipients:
                reasons.append(f"recipient mismatch: {sorted(recipients)!r}")
            expected_body = spec.get("body")
            if expected_body and not plain_text.startswith(str(expected_body)):
                reasons.append(f"body does not start with {expected_body!r}")
            source_subject = spec.get("source_subject")
            source_reference = spec.get("source_reference")
            if source_subject:
                if f"Seed body for {source_subject}." not in plain_text:
                    reasons.append(f"quoted source body for {source_subject!r} is missing")
                if str(source_reference).casefold() not in compact_references:
                    reasons.append(f"reply/forward reference for {source_subject!r} is missing")
            elif references.strip():
                reasons.append("new-message chain unexpectedly contains reply/forward references")
            for expected_attachment in spec.get("attachments") or ():
                if not cls._attachment_matches(attachments, expected_attachment):
                    reasons.append(
                        "missing attachment "
                        f"filename={expected_attachment.get('filename')!r} "
                        f"sha256={expected_attachment.get('sha256')!r}"
                    )

        passed = len(candidates) == 1 and not reasons
        check = {
            "name": str(spec["name"]),
            "steps": list(spec["steps"]),
            "durable_step": int(spec["durable_step"]),
            "dimensions": ["final_object", "content", "source_or_process"],
            "pass": passed,
            "expected": {
                "recipient": spec["recipient"],
                "sender": SENDER_EMAIL,
                "subject": spec["subject"],
                "body": spec.get("body"),
                "source_subject": spec.get("source_subject"),
                "source_reference": spec.get("source_reference"),
                "attachments": list(spec.get("attachments") or ()),
            },
            "observed": observed,
            "failure_reason": "" if passed else "; ".join(reasons),
        }
        return check, matched_date if passed else None

    @staticmethod
    def _attachment_summaries(message: Message) -> list[dict[str, Any]]:
        summaries: list[dict[str, Any]] = []
        for part in message.walk():
            if part.is_multipart():
                continue
            payload = part.get_payload(decode=True) or b""
            filename = part.get_filename()
            if not filename and part.get_content_disposition() != "attachment":
                continue
            summaries.append(
                {
                    "filename": filename,
                    "content_type": part.get_content_type(),
                    "size": len(payload),
                    "sha256": hashlib.sha256(payload).hexdigest(),
                }
            )
        return summaries

    @staticmethod
    def _attachment_matches(
        observed: list[dict[str, Any]], expected: Mapping[str, Any]
    ) -> bool:
        for attachment in observed:
            if expected.get("filename") and attachment.get("filename") != expected.get("filename"):
                continue
            if attachment.get("sha256") == expected.get("sha256"):
                return True
        return False

    @classmethod
    def _fetch_required_mailboxes(cls, api_base_url: str) -> dict[str, list[dict[str, Any]]]:
        recipients = sorted({str(spec["recipient"]) for spec in CHECKPOINT_SPECS})
        return {
            recipient: cls._fetch_mailbox(api_base_url, recipient)
            for recipient in recipients
        }

    @staticmethod
    def _fetch_mailbox(api_base_url: str, recipient: str) -> list[dict[str, Any]]:
        encoded = quote(recipient, safe="")
        request = Request(
            f"{api_base_url}/api/user/{encoded}/messages/INBOX",
            method="GET",
        )
        with urlopen(request, timeout=10) as response:
            payload = json.load(response)
        if not isinstance(payload, list):
            raise TypeError(f"mailbox payload for {recipient} must be a list")
        return [dict(item) for item in payload if isinstance(item, dict)]

    @staticmethod
    def _read_app_binding(*, udid: str, bundle_id: str) -> dict[str, Any]:
        if not udid:
            raise RuntimeError("evaluator requires the entrypoint-bound run simulator UDID")
        proc = subprocess.run(
            ["xcrun", "simctl", "get_app_container", udid, bundle_id, "data"],
            capture_output=True,
            text=True,
            timeout=30,
        )
        from platforms.ios.runtime_env.simulator_manager import remap_simulator_container_path
        container = remap_simulator_container_path(proc.stdout.strip(), udid) if proc.returncode == 0 and proc.stdout.strip() else None
        passed = bool(container and container.is_dir())
        return {
            "pass": passed,
            "udid": udid,
            "bundle_id": bundle_id,
            "data_container": str(container) if container else None,
            "read_method": "simctl get_app_container",
            "failure_reason": "" if passed else (proc.stderr.strip() or "app data container is missing"),
        }

    @classmethod
    def _resolve_causal_window(
        cls,
        *,
        context: Mapping[str, Any],
        params: Mapping[str, Any],
    ) -> tuple[datetime, datetime | None, str]:
        run_dir_raw = str(context.get("run_dir") or "").strip()
        if run_dir_raw:
            args_path = Path(run_dir_raw) / "args.json"
            if not args_path.is_file():
                raise RuntimeError(f"automatic evaluation requires {args_path}")
            payload = json.loads(args_path.read_text(encoding="utf-8-sig"))
            created_at = str(payload.get("created_at") or "").strip()
            if not created_at:
                raise RuntimeError("args.json.created_at is required for automatic causal binding")
            return cls._parse_datetime(created_at), None, "automatic_run_args_created_at"

        start_raw = str(params.get("manual_window_start") or "").strip()
        end_raw = str(params.get("manual_window_end") or "").strip()
        if not start_raw or not end_raw:
            raise RuntimeError("manual eval-only requires manual_window_start and manual_window_end")
        start = cls._parse_datetime(start_raw)
        end = cls._parse_datetime(end_raw)
        if end <= start:
            raise RuntimeError("manual causal window end must be after start")
        return start, end, "adjacent_manual_recording"

    @staticmethod
    def _parse_datetime(value: str) -> datetime:
        parsed = datetime.fromisoformat(value.replace("Z", "+00:00"))
        if parsed.tzinfo is None:
            raise ValueError(f"timezone-aware datetime required: {value!r}")
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _message_date(message: Message) -> datetime | None:
        raw = message.get("Date")
        if not raw:
            return None
        parsed = parsedate_to_datetime(raw)
        if parsed.tzinfo is None:
            return None
        return parsed.astimezone(timezone.utc)

    @staticmethod
    def _plain_text(message: Message) -> str:
        values: list[str] = []
        for part in message.walk():
            if part.get_content_type() != "text/plain":
                continue
            payload = part.get_payload(decode=True) or b""
            values.append(payload.decode(part.get_content_charset() or "utf-8", "replace"))
        return "".join(values)

    @staticmethod
    def _decode_header(value: Any) -> str:
        try:
            return str(make_header(decode_header(str(value))))
        except Exception:
            return str(value)

    @staticmethod
    def _normalize_subject(value: str) -> str:
        return re.sub(r"\s+", " ", value.replace("·", ".")).strip().casefold()

    @staticmethod
    def _build_step_coverage(checks: list[dict[str, Any]]) -> list[dict[str, Any]]:
        by_step: dict[int, dict[str, Any]] = {}
        order_pass = next(
            (
                bool(check["pass"])
                for check in checks
                if check.get("name") == "durable_submission_order"
            ),
            False,
        )
        for check in checks:
            if check["name"] == "durable_submission_order" or not check.get("steps"):
                continue
            for step in check["steps"]:
                by_step[int(step)] = {
                    "step": int(step),
                    "checkpoint": check["name"],
                    "checkpoint_names": [check["name"], "durable_submission_order"],
                    "durable_step": check.get("durable_step"),
                    "dimensions": {
                        "final_object": f"delivered MIME message at durable step {check.get('durable_step')}",
                        "content": "exact recipient, sender, subject, body, and attachment contract",
                        "source_or_process": "reply/forward source linkage plus strict global MIME Date order",
                        "final_ui": "not required after successful submission",
                    },
                    "mapping_basis": "documented compound submission chain",
                    "covered": True,
                    "pass": bool(check["pass"]) and order_pass,
                }
        return [
            by_step.get(
                step,
                {
                    "step": step,
                    "checkpoint": None,
                    "durable_step": None,
                    "covered": False,
                    "pass": False,
                },
            )
            for step in range(1, 77)
        ]

    @staticmethod
    def _error_result(
        *,
        message: str,
        api_base_url: str,
        udid: str,
        bundle_id: str,
    ) -> EvalResult:
        return EvalResult(
            status=EvalStatus.ERROR,
            message=message,
            metadata={
                "read_only": True,
                "ruleset_sha256": RULESET_SHA256,
                "instruction_sha256": INSTRUCTION_SHA256,
                "api_base_url": api_base_url,
                "udid": udid,
                "bundle_id": bundle_id,
                "safety": {
                    "http_methods": ["GET"],
                    "gui_actions": False,
                    "initializer": False,
                    "reset_or_restore": False,
                    "app_or_vm_writes": False,
                },
            },
        )
